package com.aoo.bcg.telemetry;
import com.fasterxml.jackson.databind.ObjectMapper;import com.sun.net.httpserver.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
/** Versioned ingestion route and isolated, credentialed review queue. */
public final class TelemetryHttpRoutes {private final JdbcTelemetryRiskService service;private final TelemetryAuthenticator auth;private final ObjectMapper json;private final byte[] reviewToken;public TelemetryHttpRoutes(JdbcTelemetryRiskService s,TelemetryAuthenticator a,ObjectMapper j,String token){service=s;auth=a;json=j;if(token==null||token.length()<32)throw new IllegalArgumentException("review token must contain at least 32 characters");reviewToken=token.getBytes(StandardCharsets.UTF_8);}public void mount(HttpServer server){server.createContext("/health/telemetry",e->reply(e,200,Map.of("status","UP","persistence","jdbc")));server.createContext("/v1/telemetry/signals",this::ingest);server.createContext("/internal/v1/risk/review-directives",this::review);}private void ingest(HttpExchange e)throws IOException{handle(e,()->{if(!"POST".equals(e.getRequestMethod()))throw new Api(405,"METHOD_NOT_ALLOWED","POST required");long player=auth.authenticate(e.getRequestHeaders().getFirst("Authorization"));TelemetrySignal signal=json.readValue(e.getRequestBody(),TelemetrySignal.class);return service.ingest(player,signal);});}private void review(HttpExchange e)throws IOException{handle(e,()->{if(!"GET".equals(e.getRequestMethod()))throw new Api(405,"READ_ONLY_REVIEW_QUEUE","GET required");String h=e.getRequestHeaders().getFirst("Authorization");byte[] supplied=h!=null&&h.startsWith("Bearer ")?h.substring(7).getBytes(StandardCharsets.UTF_8):new byte[0];if(!MessageDigest.isEqual(reviewToken,supplied))throw new SecurityException("valid review credential required");Map<String,String> q=query(e);return service.review(Long.parseLong(q.getOrDefault("after","0")),Integer.parseInt(q.getOrDefault("limit","50")));});}private void handle(HttpExchange e,Action a)throws IOException{try{if(!"1".equals(e.getRequestHeaders().getFirst("X-API-Version")))throw new Api(426,"API_VERSION_REQUIRED","X-API-Version: 1 required");reply(e,200,Map.of("code","OK","data",a.run()));}catch(Api x){reply(e,x.status,Map.of("code",x.code,"message",x.getMessage()));}catch(SecurityException x){reply(e,401,Map.of("code","UNAUTHORIZED","message",x.getMessage()));}catch(IllegalArgumentException x){reply(e,400,Map.of("code","INVALID_REQUEST","message",String.valueOf(x.getMessage())));}catch(IllegalStateException x){reply(e,503,Map.of("code","UNAVAILABLE","message",String.valueOf(x.getMessage())));}}private static Map<String,String> query(HttpExchange e){Map<String,String> out=new HashMap<>();String q=e.getRequestURI().getRawQuery();if(q!=null)for(String v:q.split("&")){String[]p=v.split("=",2);out.put(p[0],p.length>1?p[1]:"");}return out;}private void reply(HttpExchange e,int status,Object o)throws IOException{byte[]b=json.writeValueAsBytes(o);e.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");e.getResponseHeaders().set("Cache-Control","no-store");e.getResponseHeaders().set("X-Content-Type-Options","nosniff");e.sendResponseHeaders(status,b.length);try(var out=e.getResponseBody()){out.write(b);}}@FunctionalInterface interface Action{Object run()throws IOException;}private static final class Api extends RuntimeException{final int status;final String code;Api(int s,String c,String m){super(m);status=s;code=c;}}}
